def retry_delays(attempts, base, cap):
    if attempts < 0 or base <= 0 or cap <= 0:
        raise ValueError('invalid retry policy')
    delay = min(base, cap)
    result = []
    for _ in range(attempts):
        result.append(delay)
        delay = min(cap, delay * 2)
    return result

