def cache_lookup(cache, key, now):
    if key not in cache:
        return False, None
    value, expires = cache[key]
    if now >= expires:
        del cache[key]
        return False, None
    return True, value

def redact(value):
    if isinstance(value, dict):
        return {key: '[redacted]' if isinstance(key, str) and key.lower() in {'password','token','secret'} else redact(item) for key, item in value.items()}
    if isinstance(value, list):
        return [redact(item) for item in value]
    return value

def content_id(value):
    import hashlib, json
    text = json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False, allow_nan=False)
    return hashlib.sha256(text.encode('utf-8')).hexdigest()

