def transfer(connection, source, target, amount):
    if amount <= 0:
        raise ValueError('positive amount required')
    with connection:
        a = connection.execute('SELECT balance FROM accounts WHERE id=?', (source,)).fetchone()
        b = connection.execute('SELECT balance FROM accounts WHERE id=?', (target,)).fetchone()
        if a is None or b is None or a[0] < amount:
            raise ValueError('invalid transfer')
        connection.execute('UPDATE accounts SET balance=balance-? WHERE id=?', (amount, source))
        connection.execute('UPDATE accounts SET balance=balance+? WHERE id=?', (amount, target))

